+			    __u64 driver_data)
 {
 	struct bnxtctl_dev *bnxtctl =
 		container_of(uctx->fwctl, struct bnxtctl_dev, fwctl);
@@ -180,6 +181,9 @@ static void *bnxtctl_fw_rpc(struct fwctl_uctx *uctx,
 	struct bnxt_fw_msg rpc_in = {0};
 	int rc;
 
+	if (driver_data)
